1: /**
2:  * ALE-299: the enable / disable / status workflow for Web Push, with the
3:  * browser Push API and the Phoenix API behind two small interfaces so the
4:  * decisions are unit-tested without a service worker or a network.
5:  *
6:  * Phoenix stays authoritative for *who* gets pushed; the browser is
7:  * authoritative for whether *this installation* holds a subscription. The
8:  * toggle therefore reads its on/off state from `PushManager.getSubscription`
9:  * and treats the server row as something to keep in sync with it.
10:  */
11: 
12: import * as v from "valibot";
13: import {
14: 	decidePushAvailability,
15: 	type PushEnvironment,
16: 	urlBase64ToUint8Array,
17: } from "./availability";
18: 
19: // `PushManager.subscribe` rejects with a `NotAllowedError` DOMException when
20: // the member declines the permission prompt (or the browser auto-declines).
21: const permissionRefusalSchema = v.object({
22: 	name: v.literal("NotAllowedError"),
23: });
24: 
25: /** `PushSubscription.toJSON()` as the browser serialises it. */
26: export type BrowserSubscriptionJSON = {
27: 	endpoint: string;
28: 	expirationTime?: number | null;
29: 	keys?: { p256dh: string; auth: string };
30: };
31: 
32: export interface BrowserSubscription {
33: 	readonly endpoint: string;
34: 	/** The VAPID key this subscription was created with, when the browser reports it. */
35: 	readonly applicationServerKey: Uint8Array | null;
36: 	toJSON(): BrowserSubscriptionJSON;
37: 	unsubscribe(): Promise<boolean>;
38: }
39: 
40: /** The slice of `ServiceWorkerRegistration.pushManager` the workflow uses. */
41: export interface PushBrowser {
42: 	getSubscription(): Promise<BrowserSubscription | null>;
43: 	subscribe(applicationServerKey: Uint8Array): Promise<BrowserSubscription>;
44: }
45: 
46: export type PushServerConfig = {
47: 	enabled: boolean;
48: 	vapidPublicKey: string | null;
49: };
50: 
51: /** The three `notificationsPush.*` operations; `null`/`false` mean failure. */
52: export interface PushServer {
53: 	config(): Promise<PushServerConfig | null>;
54: 	register(
55: 		subscription: BrowserSubscriptionJSON,
56: 		userAgent: string,
57: 	): Promise<boolean>;
58: 	unregister(endpoint: string): Promise<boolean>;
59: }
60: 
61: export type PushStatus =
62: 	| { kind: "loading" }
63: 	| { kind: "server-disabled" }
64: 	| { kind: "ios-install-required" }
65: 	| { kind: "unsupported" }
66: 	| { kind: "denied" }
67: 	| { kind: "off"; vapidPublicKey: string; warning?: string }
68: 	| { kind: "on"; vapidPublicKey: string }
69: 	| {
70: 			kind: "error";
71: 			message: string;
72: 			vapidPublicKey: string | null;
73: 			/** The browser still holds a subscription the member may want to drop. */
74: 			subscribed: boolean;
75: 	  };
76: 
77: export async function determinePushStatus(input: {
78: 	/** `null` when the page has no service worker registration. */
79: 	browser: PushBrowser | null;
80: 	server: PushServer;
81: 	environment: (serverEnabled: boolean) => PushEnvironment;
82: 	userAgent: string;
83: }): Promise<PushStatus> {
84: 	const config = await input.server.config();
85: 	if (!config) {
86: 		return {
87: 			kind: "error",
88: 			message: "Couldn't check push notification settings.",
89: 			vapidPublicKey: null,
90: 			subscribed: false,
91: 		};
92: 	}
93: 
94: 	const availability = decidePushAvailability(
95: 		input.environment(config.enabled),
96: 	);
97: 	if (availability.kind !== "available") return availability;
98: 	if (!config.vapidPublicKey) return { kind: "server-disabled" };
99: 	if (!input.browser) return { kind: "unsupported" };
100: 
101: 	const vapidPublicKey = config.vapidPublicKey;
102: 	const existing = await input.browser.getSubscription().catch(() => null);
103: 	if (!existing) return { kind: "off", vapidPublicKey };
104: 
105: 	// A subscription created under a previous VAPID key can never be sent to
106: 	// again (the push service checks the key on every request). Drop it and
107: 	// report "off" so the member can opt in again under the current key.
108: 	if (!subscribedWithKey(existing, vapidPublicKey)) {
109: 		await forgetPushSubscription({
110: 			browser: input.browser,
111: 			server: input.server,
112: 		});
113: 		return { kind: "off", vapidPublicKey };
114: 	}
115: 
116: 	// Re-register on every load: an upsert on the endpoint, so it is free when
117: 	// nothing changed, rebinds a shared device to whoever is signed in now, and
118: 	// repairs a server row that was lost. Only a confirmed row is "on" — a
119: 	// browser subscription nothing will ever send to must not look enabled.
120: 	const confirmed = await input.server
121: 		.register(existing.toJSON(), input.userAgent)
122: 		.catch(() => false);
123: 	if (!confirmed) {
124: 		return {
125: 			kind: "error",
126: 			message: "Couldn't confirm this device for push notifications.",
127: 			vapidPublicKey,
128: 			subscribed: true,
129: 		};
130: 	}
131: 
132: 	return { kind: "on", vapidPublicKey };
133: }
134: 
135: // Browsers that report the key let us detect rotation; one that reports
136: // `null` (older WebKit) is trusted as-is.
137: function subscribedWithKey(
138: 	subscription: BrowserSubscription,
139: 	vapidPublicKey: string,
140: ): boolean {
141: 	if (!subscription.applicationServerKey) return true;
142: 	const expected = urlBase64ToUint8Array(vapidPublicKey);
143: 	const actual = subscription.applicationServerKey;
144: 	return (
145: 		actual.length === expected.length &&
146: 		actual.every((byte, index) => byte === expected[index])
147: 	);
148: }
149: 
150: export async function enablePush(input: {
151: 	browser: PushBrowser;
152: 	server: PushServer;
153: 	vapidPublicKey: string;
154: 	userAgent: string;
155: }): Promise<PushStatus> {
156: 	let subscription: BrowserSubscription;
157: 	try {
158: 		// This is the one call that may show the permission prompt; it only ever
159: 		// runs from the member's click on the toggle.
160: 		subscription = await input.browser.subscribe(
161: 			urlBase64ToUint8Array(input.vapidPublicKey),
162: 		);
163: 	} catch (error) {
164: 		if (v.safeParse(permissionRefusalSchema, error).success) {
165: 			return { kind: "denied" };
166: 		}
167: 		return {
168: 			kind: "error",
169: 			message: "Couldn't turn on push notifications in this browser.",
170: 			vapidPublicKey: input.vapidPublicKey,
171: 			subscribed: false,
172: 		};
173: 	}
174: 
175: 	const registered = await input.server
176: 		.register(subscription.toJSON(), input.userAgent)
177: 		.catch(() => false);
178: 
179: 	if (!registered) {
180: 		// Without the server row nothing will ever be sent here; do not leave the
181: 		// browser believing it is subscribed.
182: 		await subscription.unsubscribe().catch(() => false);
183: 		return {
184: 			kind: "error",
185: 			message: "Couldn't save this device for push notifications.",
186: 			vapidPublicKey: input.vapidPublicKey,
187: 			subscribed: false,
188: 		};
189: 	}
190: 
191: 	return { kind: "on", vapidPublicKey: input.vapidPublicKey };
192: }
193: 
194: export async function disablePush(input: {
195: 	browser: PushBrowser;
196: 	server: PushServer;
197: 	vapidPublicKey: string;
198: }): Promise<PushStatus> {
199: 	const { browserGone, serverUnregistered } =
200: 		await forgetPushSubscription(input);
201: 
202: 	if (!browserGone) {
203: 		return {
204: 			kind: "error",
205: 			message: "Couldn't turn off push notifications in this browser.",
206: 			vapidPublicKey: input.vapidPublicKey,
207: 			subscribed: true,
208: 		};
209: 	}
210: 
211: 	if (!serverUnregistered) {
212: 		return {
213: 			kind: "off",
214: 			vapidPublicKey: input.vapidPublicKey,
215: 			warning:
216: 				"Couldn't remove this device from the server. This device will stay quiet.",
217: 		};
218: 	}
219: 
220: 	return { kind: "off", vapidPublicKey: input.vapidPublicKey };
221: }
222: 
223: export type ForgetPushResult = {
224: 	/** True when this browser no longer holds a subscription. */
225: 	browserGone: boolean;
226: 	/** True when the server row is gone, or there was nothing to remove. */
227: 	serverUnregistered: boolean;
228: };
229: 
230: /**
231:  * Drops this browser's subscription on both sides, best-effort. Used by the
232:  * toggle's "off" and by sign-out: a shared device must stop receiving the
233:  * departing member's notifications, and the server row can only be removed
234:  * while their session cookie is still valid.
235:  *
236:  * `off` is only honest when the browser subscription is gone (unsubscribe
237:  * succeeded, or there was none). A failed server unregister still leaves
238:  * the device quiet (the stale row dies on the next 404/410). A failed
239:  * `getSubscription` or `unsubscribe` does not — those are not proof gone.
240:  */
241: export async function forgetPushSubscription(input: {
242: 	browser: PushBrowser | null;
243: 	server: Pick<PushServer, "unregister">;
244: }): Promise<ForgetPushResult> {
245: 	if (!input.browser) {
246: 		return { browserGone: true, serverUnregistered: true };
247: 	}
248: 
249: 	let existing: BrowserSubscription | null;
250: 	try {
251: 		existing = await input.browser.getSubscription();
