1: /**
2:  * ALE-299: decides whether this browser can offer Web Push, and why not.
3:  *
4:  * Pure: every environment fact is passed in, so the decision is unit-tested
5:  * without a browser and the component only has to read the facts. The order
6:  * of the checks is the user-facing explanation order — a server without keys
7:  * is the deployment's problem, an iOS browser tab is an install problem, a
8:  * missing API is a browser problem, and a denial is a permission the user
9:  * changed and must change back themselves (we never prompt again).
10:  */
11: 
12: export type PushEnvironment = {
13: 	/** `GET /notifications/push/config` said push is configured. */
14: 	serverEnabled: boolean;
15: 	hasServiceWorker: boolean;
16: 	hasPushManager: boolean;
17: 	hasNotification: boolean;
18: 	permission: NotificationPermission | null;
19: 	isIOS: boolean;
20: 	/** Running as an installed web app (standalone display mode). */
21: 	isStandalone: boolean;
22: };
23: 
24: export type PushAvailability =
25: 	| { kind: "server-disabled" }
26: 	| { kind: "ios-install-required" }
27: 	| { kind: "unsupported" }
28: 	| { kind: "denied" }
29: 	| { kind: "available"; permission: "default" | "granted" };
30: 
31: export function decidePushAvailability(env: PushEnvironment): PushAvailability {
32: 	if (!env.serverEnabled) return { kind: "server-disabled" };
33: 
34: 	// iOS grants Web Push only to web apps added to the Home Screen, whatever
35: 	// the browser and whether or not a PushManager object happens to exist in
36: 	// the tab. The fix is to install, not to switch browser.
37: 	if (env.isIOS && !env.isStandalone) {
38: 		return { kind: "ios-install-required" };
39: 	}
40: 
41: 	if (!env.hasServiceWorker || !env.hasPushManager || !env.hasNotification) {
42: 		return { kind: "unsupported" };
43: 	}
44: 
45: 	if (env.permission === "denied") return { kind: "denied" };
46: 
47: 	return {
48: 		kind: "available",
49: 		permission: env.permission === "granted" ? "granted" : "default",
50: 	};
51: }
52: 
53: /**
54:  * Reads the environment facts from a window. Split from the decision so the
55:  * decision stays pure; kept tolerant because feature detection runs before we
56:  * know anything about the browser.
57:  */
58: export function readPushEnvironment(
59: 	win: Window & typeof globalThis,
60: 	serverEnabled: boolean,
61: ): PushEnvironment {
62: 	const nav = win.navigator;
63: 	const ua = nav.userAgent ?? "";
64: 	// iPadOS reports a Mac UA; touch points tell it apart from a real Mac.
65: 	const isIOS =
66: 		/iPad|iPhone|iPod/.test(ua) ||
67: 		(nav.platform === "MacIntel" && (nav.maxTouchPoints ?? 0) > 1);
68: 	// SAFETY: `navigator.standalone` is a non-standard iOS Safari property the
69: 	// DOM lib does not declare; it is read with optional chaining and compared
70: 	// to `true`, so an absent property is simply "not standalone".
71: 	const standaloneNavigator = nav as Navigator & { standalone?: boolean };
72: 	const isStandalone =
73: 		win.matchMedia?.("(display-mode: standalone)").matches === true ||
74: 		standaloneNavigator.standalone === true;
75: 
76: 	return {
77: 		serverEnabled,
78: 		hasServiceWorker: "serviceWorker" in nav,
79: 		hasPushManager: "PushManager" in win,
80: 		hasNotification: "Notification" in win,
81: 		permission: "Notification" in win ? win.Notification.permission : null,
82: 		isIOS,
83: 		isStandalone,
84: 	};
85: }
