92: export function urlBase64ToUint8Array(base64Url: string): Uint8Array {
93: 	const padding = "=".repeat((4 - (base64Url.length % 4)) % 4);
94: 	const base64 = (base64Url + padding).replace(/-/g, "+").replace(/_/g, "/");
95: 	const raw = atob(base64);
96: 	const bytes = new Uint8Array(raw.length);
97: 	for (let i = 0; i < raw.length; i += 1) bytes[i] = raw.charCodeAt(i);
98: 	return bytes;
99: }

